class Manager {
    int status_code_ = 0;
    std::string log_file_ = "/var/log/sys.log";

public:
    // Returns constant reference (const T&)
    // Ensures immutability and avoids copying.
    const std::string&
    getLogFile() const noexcept
    {
        return log_file_;
    }

    // Uses noexcept specifier
    // Guarantees no exceptions thrown, enabling optimization.
    const int&
    getStatus() const noexcept
    {
        return status_code_;
    }
};
